function summarize(n, depth) {
  const o = { id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
  if ('fills' in n) { try { o.fills = JSON.stringify(n.fills).slice(0, 260); } catch (e) {} }
  if ('cornerRadius' in n) o.radius = n.cornerRadius;
  if (n.type === 'TEXT') { o.font = JSON.stringify(n.fontName); o.size = n.fontSize; o.chars = n.characters.slice(0, 60); }
  if (depth > 0 && 'children' in n) o.children = n.children.map(c => summarize(c, depth - 1));
  return o;
}
