function recolor(node,colorHex){
  const paint=S(colorHex);
  let all=[]; try{all=node.findAll(()=>true);}catch(e){}
  for(const n of all){
    if(['TEXT','VECTOR','ELLIPSE','RECTANGLE','LINE','BOOLEAN_OPERATION'].includes(n.type)){
      try{ if(Array.isArray(n.fills)&&n.fills.length&&n.fills.some(f=>f.type==='SOLID')) n.fills=n.fills.map(f=>f.type==='SOLID'?{...paint,opacity:f.opacity}:f);}catch(e){}
