const hx=(h)=>{const n=parseInt(h.slice(1),16);return{r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255}};
const S=(h,o=1)=>({type:'SOLID',color:hx(h),opacity:o});
function recolor(node,colorHex){
  const paint=S(colorHex);
  let all=[]; try{all=node.findAll(()=>true);}catch(e){}
  for(const n of all){
    if(['TEXT','VECTOR','ELLIPSE','RECTANGLE','LINE','BOOLEAN_OPERATION'].includes(n.type)){
      try{ if(Array.isArray(n.fills)&&n.fills.length&&n.fills.some(f=>f.type==='SOLID')) n.fills=n.fills.map(f=>f.type==='SOLID'?{...paint,opacity:f.opacity}:f);}catch(e){}
      try{ if(Array.isArray(n.strokes)&&n.strokes.length&&n.strokes.some(f=>f.type==='SOLID')) n.strokes=n.strokes.map(f=>f.type==='SOLID'?{...paint,opacity:f.opacity}:f);}catch(e){}
    }
  }
}
function txt(chars,size,style,color,opts={}){
  const t=figma.createText();
  t.fontName=F(style); t.characters=chars; t.fontSize=size; t.fills=[S(color,opts.o===undefined?1:opts.o)];
  if(opts.ls) t.letterSpacing={value:opts.ls,unit:'PERCENT'};
  if(opts.lh) t.lineHeight={value:opts.lh,unit:'PIXELS'};
  if(opts.w){t.textAutoResize='NONE'; t.resize(opts.w,opts.h||Math.round(size*1.4));}
  if(opts.align) t.textAlignHorizontal=opts.align;
  if(opts.trunc) t.textTruncation='ENDING';
  if(opts.name) t.name=opts.name;
  return t;
}
